parameters.functionCode:
const body = $input.first().json.body;
const message = body.message.toLowerCase();

// Parse time preference from message
const timePatterns = [
  /(?:jam|at|pukul)\s*(\d{1,2})[:.](\d{2})/i,
  /(?:jam|at|pukul)\s*(\d{1,2})\s*(pagi|siang|sore|malam|am|pm)/i,
  /(\d{1,2})[:.](\d{2})\s*(pagi|siang|sore|malam|am|pm)?/i
];

let requestedHour = null;
let requestedMinute = 0;

for (const pattern of timePatterns) {
  const match = message.match(pattern);
  if (match) {
    requestedHour = parseInt(match[1]);
    requestedMinute = match[2] ? parseInt(match[2]) : 0;
    break;
  }
}

// Parse date preference
const today = new Date();
let requestedDate = new Date(today);

if (message.includes('besok') || message.includes('tomorrow')) {
  requestedDate.setDate(requestedDate.getDate() + 1);
} else if (message.includes('lusa')) {
  requestedDate.setDate(requestedDate.getDate() + 2);
}

return [{
  json: {
    customer_phone: body.from,
    customer_name: body.profile_name || 'Customer',
    raw_message: body.message,
    requested_date: requestedDate.toISOString().split('T')[0],
    requested_hour: requestedHour,
    requested_minute: requestedMinute,
    parsed_ok: requestedHour !== null
  }
}];

